class Solution {
  public long minEnd(int n, int x) {
    long result = x, value = n - 1L;
    // spread the bits of n - 1 over the zero bits of x; bit can pass 31, so shift x as a long
    for (int bit = 0; value > 0; bit++) {
      if (((long) x >> bit & 1) == 0) {
        if ((value & 1) != 0) result |= 1L << bit;
        value >>= 1;
      }
    }
    return result;
  }
}
